// #8d9668 (6a993d6ab96217a9f48d9668) — отчёт с плеером записи, синхронным с транскриптом.
// По ГОТОВОМУ отчёту QA-bf7c47-2110 (39 с, 7 сегментов, 3 рекомендованных фрагмента; новых звонков нет). Кейсы REC-007…REC-011.
//  - время mm:ss; говорящий «<имя> · מועמד/ת» / «<персона> · לקוח» (у симуляции без имени персоны — «לקוח»);
//  - клик по цитате / времени / сегменту → перемотка к началу (±0.5 с) и воспроизведение; активный сегмент подсвечен синхронно;
//  - рекомендованный фрагмент играет со своего начала;
//  - get-recording-url 500 (подмена) → «לא הצלחנו לטעון את ההקלטה.» + «טעינה מחדש», повтор работает; без входа (anon) → 401.
// Только чтение (воспроизведение ставится на паузу) → @prod-safe. Отчёт business — только десктоп (L-20261014-5).
import * as path from 'path';
import { Locator, Page } from '@playwright/test';
import { test, expect } from '@playwright/test';
import { openWithApi, SUPABASE_URL } from '../support/api';
import { candidateId, getReport } from '../candidates/hiring-support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#8d9668 · #6a993d6ab96217a9f48d9668';
const CANDIDATE = process.env.QA_PLAYER_CANDIDATE || 'QA-bf7c47-2110';
const TOLERANCE = 0.5;
const RECORDING_URL = /\/functions\/v1\/get-recording-url/;

/** Открыть отчёт кандидата; дождаться метаданных записи; начать запоминать перемотки (seeked). */
async function openPlayer(page: Page) {
  const api = await openWithApi(page, '/candidates');
  const id = await candidateId(api, CANDIDATE);
  await page.goto(`/candidates/${id}/report`);
  await expect(page.getByTestId('recording-player')).toBeVisible({ timeout: 30_000 });
  await expect.poll(() => page.evaluate(() => document.querySelector('audio')?.readyState ?? 0), { message: 'запись не загрузилась', timeout: 20_000 }).toBeGreaterThanOrEqual(1);
  await page.evaluate(() => {
    const a = document.querySelector('audio')!;
    const w = window as unknown as { __seeks: number[] };
    w.__seeks = [];
    a.addEventListener('seeked', () => w.__seeks.push(a.currentTime));
  });
  return { api, id };
}

const lastSeek = (page: Page) => page.evaluate(() => (window as unknown as { __seeks: number[] }).__seeks.at(-1) ?? -1);
const isPlaying = (page: Page) => page.evaluate(() => !document.querySelector('audio')!.paused);
const pause = (page: Page) => page.evaluate(() => document.querySelector('audio')!.pause());

/** Поставить запись в точку away (не рядом с целью), очистить журнал перемоток, кликнуть target. */
async function clickFrom(page: Page, target: Locator, away: number) {
  await page.evaluate((t) => { document.querySelector('audio')!.currentTime = t; }, away);
  await expect.poll(() => lastSeek(page)).toBeCloseTo(away, 0);
  await page.evaluate(() => { (window as unknown as { __seeks: number[] }).__seeks = []; });
  await target.click();
}

/** После клика: перемотка к start (±0.5 с) и воспроизведение. */
async function expectSeekAndPlay(page: Page, start: number, what: string) {
  await expect
    .poll(async () => Math.abs((await lastSeek(page)) - start) <= TOLERANCE, { message: `${what}: перемотка к ${start} с (±${TOLERANCE})` })
    .toBe(true);
  await expect.poll(() => isPlaying(page), { message: `${what}: воспроизведение` }).toBe(true);
}

test.describe(`Отчёт — плеер записи, синхронный с транскриптом (${HASH})`, () => {
  test(`${CANDIDATE}: время mm:ss; говорящие «${CANDIDATE} · מועמד/ת» и «… · לקוח»/«לקוח» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openPlayer(page);
    const segments = page.getByTestId('transcript-segment');
    await expect(segments.first()).toBeVisible();

    // Источник: Figma 678:654 (реджект 14.10) — время mm:ss.
    const times = await page.getByTestId('segment-time').allInnerTexts();
    expect(times.length).toBeGreaterThan(0);
    for (const t of times) expect(t.trim(), 'время сегмента').toMatch(/^\d{2}:\d{2}$/);
    for (const t of await page.getByTestId('evidence-time').allInnerTexts()) expect(t.trim(), 'время цитаты').toMatch(/^\d{2}:\d{2}$/);
    const playerTimes = await page.getByTestId('recording-player').locator('bdi').allInnerTexts();
    expect(playerTimes.length).toBeGreaterThanOrEqual(2);
    for (const t of playerTimes) expect(t.trim(), 'время плеера').toMatch(/^\d{2}:\d{2}$/);

    // Источник: Figma 678:654 — подпись говорящего с именем и ролью.
    const speakers = await segments.evaluateAll((els) =>
      els.map((el) => ({ who: el.getAttribute('data-speaker'), label: el.querySelector('span > span')?.textContent?.trim() ?? '' })),
    );
    const candidate = speakers.filter((s) => s.who === 'candidate');
    const customer = speakers.filter((s) => s.who === 'customer');
    expect(candidate.length).toBeGreaterThan(0);
    expect(customer.length).toBeGreaterThan(0);
    for (const s of candidate) expect(s.label).toBe(`${CANDIDATE} · מועמד/ת`);
    for (const s of customer) expect(s.label).toMatch(/^(?:.+ · )?לקוח$/);
  });

  test(`${CANDIDATE}: клик по цитате, времени цитаты и сегменту — перемотка к началу ±0.5 с и звук; активный сегмент подсвечен синхронно @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openPlayer(page);

    // 1) Цитата домена «פתיחת השיחה» 00:05 (начало сегмента 5.97 с).
    const opening = page.locator('[data-testid="report-domain"][data-domain="opening"] [data-testid="domain-evidence"]');
    const quoteStart = 5.97;
    await clickFrom(page, opening.getByRole('button', { name: /^האזנה לציטוט מ־00:05: «/ }).first(), 30);
    await expectSeekAndPlay(page, quoteStart, 'цитата 00:05');
    await pause(page);

    // 2) Время цитаты «00:05 ▶».
    await clickFrom(page, opening.getByRole('button', { name: 'האזנה לציטוט מ־00:05', exact: true }).first(), 30);
    await expectSeekAndPlay(page, quoteStart, 'время цитаты 00:05');
    await pause(page);

    // 3) Сегмент транскрипта 00:22 (клиент, 22.47–29.61 с): перемотка, звук, подсветка этого сегмента.
    const segment = page.getByTestId('transcript-segment').filter({ has: page.getByTestId('segment-time').getByText('00:22', { exact: true }) });
    await expect(segment).toHaveCount(1);
    const start = Number(await segment.getAttribute('data-start'));
    await clickFrom(page, segment, 2);
    await expectSeekAndPlay(page, start, 'сегмент 00:22');
    await expect(segment, 'активный сегмент').toHaveAttribute('aria-current', 'true');
    await expect(page.locator('[data-testid="transcript-segment"][aria-current="true"]')).toHaveCount(1);

    // Синхронность: при воспроизведении подсветка переходит на следующий сегмент вместе со временем записи.
    const next = page.locator('[data-testid="transcript-segment"]').filter({ has: page.getByTestId('segment-time').getByText('00:29', { exact: true }) });
    await expect(next, 'подсветка перешла на сегмент 00:29').toHaveAttribute('aria-current', 'true', { timeout: 15_000 });
    const sync = await page.evaluate(() => {
      const t = document.querySelector('audio')!.currentTime;
      const cur = document.querySelector('[data-testid="transcript-segment"][aria-current="true"]')!;
      return { t, start: Number(cur.getAttribute('data-start')), end: Number(cur.getAttribute('data-end')) };
    });
    expect(sync.t, `время ${sync.t} внутри активного сегмента ${sync.start}–${sync.end}`).toBeGreaterThanOrEqual(sync.start - TOLERANCE);
    expect(sync.t).toBeLessThanOrEqual(sync.end + TOLERANCE);
    await expect(segment).not.toHaveAttribute('aria-current', 'true');
    await pause(page);
  });

  test(`${CANDIDATE}: рекомендованный фрагмент играет со своего начала @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openPlayer(page);
    const clips = page.getByTestId('report-clips').getByTestId('clip');
    await expect(clips).toHaveCount(3);
    for (let i = 0; i < 3; i++) {
      const clip = clips.nth(i);
      const start = Number(await clip.getAttribute('data-start'));
      // Источник: AC — «השמעת הקטע mm:ss–mm:ss» перематывает к началу фрагмента и запускает звук.
      await clickFrom(page, clip.getByRole('button', { name: /^השמעת הקטע / }), 37);
      await expectSeekAndPlay(page, start, `фрагмент ${i + 1}`);
      await pause(page);
    }
  });

  test(`get-recording-url 500 → «לא הצלחנו לטעון את ההקלטה.» и «טעינה מחדש»; транскрипт на месте; повтор загружает запись @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/candidates');
    const id = await candidateId(api, CANDIDATE);
    await page.route(RECORDING_URL, (r) =>
      r.request().method() === 'POST' ? r.fulfill({ status: 500, contentType: 'application/json', body: '{"error":"qa"}' }) : r.continue(),
    );
    await page.goto(`/candidates/${id}/report`);

    // Источник: AC (сбой загрузки записи) — понятное сообщение и повтор, отчёт и транскрипт доступны.
    const player = page.getByTestId('recording-player');
    const alert = player.getByRole('alert');
    await expect(alert).toContainText('לא הצלחנו לטעון את ההקלטה.', { timeout: 30_000 });
    const retry = alert.getByRole('button', { name: 'טעינה מחדש' });
    await expect(retry).toBeVisible();
    await expect(page.getByTestId('transcript-segment').first()).toBeVisible();
    await expect(player.locator('audio')).toHaveCount(0);

    await page.unroute(RECORDING_URL);
    const again = page.waitForResponse((r) => RECORDING_URL.test(r.url()) && r.request().method() === 'POST');
    await retry.click();
    expect((await again).status(), 'повторный get-recording-url').toBe(200);
    await expect.poll(() => page.evaluate(() => document.querySelector('audio')?.readyState ?? 0), { message: 'запись после «טעינה מחדש»', timeout: 20_000 }).toBeGreaterThanOrEqual(1);
    await expect(player.getByRole('alert')).toHaveCount(0);
  });

  test(`get-recording-url без входа (anon) → 401; с сессией business → 200 @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/candidates');
    const report = (await getReport(api, await candidateId(api, CANDIDATE))) as unknown as { recording: { id: string } | null };
    expect(report.recording?.id, 'у отчёта нет записи').toBeTruthy();
    const url = `${SUPABASE_URL}/functions/v1/get-recording-url`;
    const data = { recording_id: report.recording!.id };

    // Источник: AC (доступ к записи только своим) — анонимный ключ без сессии получает 401.
    const anon = await page.request.post(url, {
      headers: { apikey: api.headers.apikey, authorization: `Bearer ${api.headers.apikey}`, 'content-type': 'application/json' },
      data,
    });
    expect(anon.status(), await anon.text()).toBe(401);

    const own = await page.request.post(url, { headers: api.headers, data });
    expect(own.status(), await own.text()).toBe(200);
  });
});
